long long cp[MAXN][MAXN]; // col prefix: cp[r][c] = sum of col c from row 0..r-1

long long row_sum(int r, int c1, int c2) { return rp[r][c2+1] - rp[r][c1]; }
long long col_sum(int c, int r1, int r2) { if(r1>r2) return 0; return cp[r2+1][c] - cp[r1][c]; }

