                    // Border sum = sum of all pixels on the perimeter
                    // Top row: (r1, c1) to (r1, c2)
                    // Bottom row: (r2, c1) to (r2, c2)
                    // Left column: (r1+1, c1) to (r2-1, c1)
                    // Right column: (r1+1, c2) to (r2-1, c2)

