        for (int j = 0; j < N; j++) {
            scanf("%lld", &a[i][j]);
            ps[i + 1][j + 1] = ps[i + 1][j] + ps[i][j + 1] - ps[i][j] + a[i][j];
        }
    }

    long long ans = -(1LL << 60);

    for (int r1 = 0; r1 < N; r1++) {
        for (int r2 = r1; r2 < N; r2++) {
            for (int c1 = 0; c1 < N; c1++) {
                for (int c2 = c1; c2 < N; c2++) {
                    long long total = ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1] - ps[r2 + 1][c1] + ps[r1][c1];
                    int h = r2 - r1 + 1;
                    int w = c2 - c1 + 1;

                    long long border = total;
                    if (h >= 3 && w >= 3) {
                        long long inner = ps[r2][c2] - ps[r1 + 1][c2] - ps[r2][c1 + 1] + ps[r1 + 1][c1 + 1];
                        border -= inner;
                    }

                    ans = maxll(ans, border);
