            for (int j = 0; j < N; j++) {
                pref[i + 1][j + 1] = pref[i + 1][j] + pref[i][j + 1] - pref[i][j] + a[i][j];
            }
        }

        long best = Long.MIN_VALUE;

        // iterate over all possible top-left and bottom-right corners
        for (int r1 = 0; r1 < N; r1++) {
            for (int c1 = 0; c1 < N; c1++) {
                for (int r2 = r1; r2 < N; r2++) {
                    for (int c2 = c1; c2 < N; c2++) {
                        // border condition: at least one dimension is 1 or 2 pixels
                        int h = r2 - r1 + 1;
                        int w = c2 - c1 + 1;
                        if (h == 1 || w == 1 || h == 2 || w == 2) {
                            // sum of whole rectangle
                            long total = pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
                            // subtract interior if h>=3 and w>=3
                            if (h >= 3 && w >= 3) {
                                long interior = pref[r2][c2] - pref[r1 + 1][c2] - pref[r2][c1 + 1] + pref[r1 + 1][c1 + 1];
                                total -= interior;
                            }
                            if (total > best) best = total;
                        }
                    }
                }
            }
        }

        System.out.println(best);
