public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[][] a = new long[N + 1][N + 1];
        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= N; j++) {
                a[i][j] = fs.nextLong();
            }
        }

        // 2D prefix sum
        long[][] ps = new long[N + 1][N + 1];
        for (int i = 1; i <= N; i++) {
            long row = 0;
            for (int j = 1; j <= N; j++) {
                row += a[i][j];
                ps[i][j] = ps[i - 1][j] + row;
            }
        }

        long ans = Long.MIN_VALUE;

        // Enumerate top and bottom rows
        for (int top = 1; top <= N; top++) {
            for (int bottom = top; bottom <= N; bottom++) {
                int h = bottom - top + 1;

                long[] col = new long[N + 1]; // sum on each column from top..bottom
                for (int c = 1; c <= N; c++) {
                    col[c] = rectSum(ps, top, c, bottom, c);
                }

                if (h <= 2) {
                    // Border equals the whole rectangle
                    long cur = 0;
                    for (int r = 1; r <= N; r++) {
                        cur += col[r];
                        if (cur > ans) ans = cur;
                        if (cur < 0) cur = 0;
                    }

                    // Need to handle all-negative correctly
                    long single = Long.MIN_VALUE;
                    for (int r = 1; r <= N; r++) single = Math.max(single, col[r]);
                    ans = Math.max(ans, single);
                } else {
                    // For width 1 or 2, border equals whole rectangle
                    ans = Math.max(ans, maxSubarrayAtMost2(col, N));

                    // For width >= 3:
                    // border sum of columns l..r:
                    // sum(col[l..r]) - inner_sum(top+1..bottom-1, l+1..r-1)
                    // = (col[l] + col[r]) + sum(top row + bottom row on middle columns)
                    //
                    // Let mid[c] = a[top][c] + a[bottom][c]
                    // Then for width >= 3:
                    // value = col[l] + col[r] + sum(mid[l+1..r-1])
                    //
                    // Rewrite as:
                    // value = (col[l] - prefixMid[l]) + (prefixMid[r-1] + col[r])
                    long[] prefMid = new long[N + 1];
                    for (int c = 1; c <= N; c++) {
                        prefMid[c] = prefMid[c - 1] + a[top][c] + a[bottom][c];
                    }

                    long bestLeft = Long.MIN_VALUE;
                    for (int r = 3; r <= N; r++) {
                        int lCand = r - 2;
                        long valLeft = col[lCand] - prefMid[lCand];
                        if (valLeft > bestLeft) bestLeft = valLeft;

                        long value = bestLeft + prefMid[r - 1] + col[r];
                        if (value > ans) ans = value;
                    }
                }
            }
        }

        System.out.println(ans);
    }

    static long rectSum(long[][] ps, int r1, int c1, int r2, int c2) {
        return ps[r2][c2] - ps[r1 - 1][c2] - ps[r2][c1 - 1] + ps[r1 - 1][c1 - 1];
    }

    static long maxSubarrayAtMost2(long[] arr, int n) {
        long res = Long.MIN_VALUE;
        for (int i = 1; i <= n; i++) {
            res = Math.max(res, arr[i]); // width 1
            if (i >= 2) res = Math.max(res, arr[i - 1] + arr[i]); // width 2
        }
        return res;
    }
}

