int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> a(N, vector<int>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> a[i][j];
        }
    }

    // Prefix sums for O(1) rectangle sum
    vector<vector<long long>> pref(N + 1, vector<long long>(N + 1, 0));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            pref[i+1][j+1] = pref[i][j+1] + pref[i+1][j] - pref[i][j] + a[i][j];
        }
    }

    auto rect_sum = [&](int r1, int c1, int r2, int c2) -> long long {
        if (r1 > r2 || c1 > c2) return 0;
        return pref[r2+1][c2+1] - pref[r1][c2+1] - pref[r2+1][c1] + pref[r1][c1];
    };

    long long ans = LLONG_MIN;

    // Enumerate top-left (r1, c1) and bottom-right (r2, c2)
    for (int r1 = 0; r1 < N; r1++) {
        for (int c1 = 0; c1 < N; c1++) {
            for (int r2 = r1; r2 < N; r2++) {
                for (int c2 = c1; c2 < N; c2++) {
                    int h = r2 - r1 + 1;
                    int w = c2 - c1 + 1;
                    if (h == 1 && w == 1) {
                        // Single pixel: border is just that pixel
                        ans = max(ans, (long long)a[r1][c1]);
                    } else {
                        // Sum of border: top row + bottom row + left column + right column
                        // Subtract corners counted twice
                        long long border = rect_sum(r1, c1, r1, c2); // top row
                        border += rect_sum(r2, c1, r2, c2); // bottom row
                        border += rect_sum(r1, c1, r2, c1); // left column
                        border += rect_sum(r1, c2, r2, c2); // right column
                        // Subtract corners (each counted twice)
                        border -= a[r1][c1];
                        border -= a[r1][c2];
                        border -= a[r2][c1];
                        border -= a[r2][c2];
                        // If height or width is 1, some rows/cols overlap; adjust
                        if (h == 1) {
                            // top and bottom same row, left and right same row
                            // Actually for h==1, border is just the row segment from c1 to c2
                            // Our formula would double count, so handle separately
                            border = rect_sum(r1, c1, r1, c2);
                        } else if (w == 1) {
                            // similarly for w==1
                            border = rect_sum(r1, c1, r2, c1);
                        } else {
                            // For h>=2 and w>=2, corners already subtracted correctly
                            // But if h==2, top and bottom rows are distinct, left/right columns touch both rows
                            // Our formula still works because we subtract all 4 corners
                        }
                        ans = max(ans, border);
                    }
                }
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

