import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    # Read matrix row by row
    a = [[0] * (n + 1) for _ in range(n + 1)]  # 1-indexed
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            a[i][j] = int(next(it))

    # Build 2D prefix sum
    pref = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        row_sum = 0
        for j in range(1, n + 1):
            row_sum += a[i][j]
            pref[i][j] = pref[i-1][j] + row_sum

    def rect_sum(r1, c1, r2, c2):
        # inclusive rectangle sum
        return (pref[r2][c2] - pref[r1-1][c2] - pref[r2][c1-1] + pref[r1-1][c1-1])

    max_sum = -10**18

    # Enumerate all possible top-left (i1,j1) and bottom-right (i2,j2)
    for i1 in range(1, n + 1):
        for j1 in range(1, n + 1):
            for i2 in range(i1, n + 1):
                for j2 in range(j1, n + 1):
                    h = i2 - i1 + 1
                    w = j2 - j1 + 1
                    # total sum of the rectangle
                    total = rect_sum(i1, j1, i2, j2)
                    if h >= 3 and w >= 3:
                        # subtract inner rectangle
                        inner = rect_sum(i1 + 1, j1 + 1, i2 - 1, j2 - 1)
                        border_sum = total - inner
                    else:
                        # For thin rectangles, the whole rectangle is the border
                        border_sum = total
                    if border_sum > max_sum:
                        max_sum = border_sum
    print(max_sum)

if __name__ == "__main__":
    solve()
